+    buffer.write(
+      '{"type":"message","id":"e$i","parentId":'
+      '${i == 0 ? 'null' : '"e${i - 1}"'},"timestamp":"$iso",'
+      '"message":{"role":"user","content":[{"type":"text","text":'
+      '"message $i with a bit of body to be realistic"}]}}\n',
