  final int? count;
  try {
    count = await windowed.countAbove();
  } on Object {
    return;
  }
  if (gen != _loadGeneration) return;
  if (_historyAboveCount != count || windowed.cachedTotalRecords != null) {
    _historyAboveCount = count;
    _notify();
  }
}

